"use strict";

/* ---------- localStorage 封装 ---------- */
const Store = {
  get(key, fallback) {
    try {
      const v = localStorage.getItem("heuprep:" + key);
      return v === null ? fallback : JSON.parse(v);
    } catch (e) { return fallback; }
  },
  set(key, value) {
    try { localStorage.setItem("heuprep:" + key, JSON.stringify(value)); } catch (e) {}
  },
  del(key) { try { localStorage.removeItem("heuprep:" + key); } catch (e) {} }
};

