/* ---------- 通用工具 ---------- */
function h(tag, attrs = {}, children = "") {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "class") el.className = v;
    else if (k === "html") el.innerHTML = v;
    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
    else el.setAttribute(k, v);
  }
  if (children) el.innerHTML += children;
  return el;
}
function fmtDate(d) {
  const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, "0"), dd = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${dd}`;
}
function daysUntil(dateStr) {
  const target = new Date(dateStr + "T00:00:00");
  const now = new Date(); now.setHours(0, 0, 0, 0);
  return Math.round((target - now) / 86400000);
}
function mondayOf(date) {
  const d = new Date(date); d.setHours(0, 0, 0, 0);
  const shift = (d.getDay() + 6) % 7;
  d.setDate(d.getDate() - shift);
  return d;
}
function badge(track) { return `<span class="badge ${track}">${track === "zikao" ? "自考" : "考研"}</span>`; }
function dateTypeBadge(dt) {
  const map = { confirmed: "已公布", expected: "预计", tba: "待公布" };
  return `<span class="dt dt-${dt}">${map[dt] || dt}</span>`;
}
function subjectName(code) {
  if (code.startsWith("408-")) {
    const s = SITE_DATA.kaoyan.exam408.subjects.find(x => x.code === code);
    return s ? s.name : code;
  }
  const c = SITE_DATA.zikao.courses.find(x => x.code === code);
  return c ? `${c.code} ${c.name}` : code;
}

/* ---------- 倒计时 ---------- */
function nextZikaoDate() {
  /* 仅返回“今天及以后”的 confirmed 日期 */
  const today = fmtDate(new Date());
  const evs = SITE_DATA.timeline
    .filter(e => e.track === "zikao" && e.date_type === "confirmed" && e.date_end && e.date_end >= today)
    .sort((a, b) => a.date_start.localeCompare(b.date_start));
  return evs.length ? evs[0] : null;
}
function renderCountdowns() {
  const root = document.getElementById("countdown-cards");
  if (!root) return;
  const kyDays = daysUntil(SITE_DATA.countdown.kaoyan_target);
  const zk = nextZikaoDate();
  const custom = Store.get("custom_countdown", null);
  root.innerHTML = `
    <div class="countdown-card">
      <div class="cd-label">${badge("kaoyan")} 28 考研初试倒计时</div>
      <div class="cd-num">${kyDays}<small>天</small></div>
      <div class="cd-target">目标 ${SITE_DATA.countdown.kaoyan_target}</div>
      <div class="cd-note">预计日期，以教育部公告为准</div>
    </div>
    <div class="countdown-card">
      <div class="cd-label">${badge("zikao")} 下一次自考</div>
      ${zk
        ? `<div class="cd-num">${daysUntil(zk.date_start)}<small>天</small></div>
           <div class="cd-target">${zk.date_start} ~ ${zk.date_end}（已公布）</div>`
        : `<div class="cd-num" style="font-size:30px;font-weight:400;line-height:1.4;">待官方公布</div>
           <div class="cd-target">下一次考期待官方公布</div>`}
    </div>
    <div class="countdown-card">
      <div class="cd-label">自定义倒计时</div>
      ${custom
        ? `<div class="cd-num">${Math.max(0, daysUntil(custom.date))}<small>天</small></div>
           <div class="cd-target">${custom.label || "自定义"} · ${custom.date}</div>`
        : `<div class="cd-num" style="font-size:30px;font-weight:400;line-height:1.4;">未设置</div>`}
      <input type="date" id="custom-cd-date" value="${custom ? custom.date : ""}">
      <input type="text" id="custom-cd-label" placeholder="名称（可选）" value="${custom ? custom.label || "" : ""}" style="width:100%;margin-top:6px;">
      <div style="margin-top:8px;display:flex;gap:8px;">
        <button class="btn small" id="custom-cd-save">保存</button>
        ${custom ? `<button class="btn small ghost" id="custom-cd-clear">清除</button>` : ""}
      </div>
    </div>`;
  const save = document.getElementById("custom-cd-save");
  if (save) save.addEventListener("click", () => {
    const date = document.getElementById("custom-cd-date").value;
    if (!date) return alert("请选择日期");
    Store.set("custom_countdown", { date, label: document.getElementById("custom-cd-label").value });
    renderCountdowns();
  });
  const clear = document.getElementById("custom-cd-clear");
  if (clear) clear.addEventListener("click", () => { Store.del("custom_countdown"); renderCountdowns(); });
}

